function successMessageCard8(e,t=null){const a=`\n            <div class="fixed inset-0 bg-black/20 flex justify-center items-center z-50" id="success-message">\n                  <div class="bg-white dark:bg-gray-900 w-[23%] h-auto shadow-md rounded-sm flex flex-col justify-center items-center p-6 text-center gap-4 fade-in-up">\n                        <i data-lucide="circle-check" class="w-15 h-15 text-green-500"></i>\n                        <h2 class="text-lg text-gray-600 dark:text-white" id="message">${e}</h2>\n                        <button class="bg-blue-500 p-1 text-white rounded-lg mt-6 hover:bg-blue-600 px-6 py-2" id="close-message">Okay</button>\n                  </div>\n            </div>\n      `;document.getElementById("messagePortal").innerHTML+=a,lucide.createIcons(),document.getElementById("close-message").addEventListener("click",()=>{document.querySelector("#success-message").remove(),t&&(window.location.href=t)})}function failedMessageCard8(e){const t=`\n            <div class="fixed inset-0 bg-black/20 flex justify-center items-center z-50" id="failed-message">\n                  <div class="bg-white dark:bg-gray-900 w-[23%] h-auto shadow-md rounded-sm flex flex-col justify-center items-center p-6 text-center gap-4 fade-in-up ">\n                        <i data-lucide="circle-x" class="w-15 h-15 text-center font-bold text-red-500"></i>\n                        <h2 class="text-lg text-gray-600 dark:text-white" id="message">${e}</h2>\n                        <button class="bg-blue-500 p-1 text-white rounded-lg mt-6 hover:bg-blue-600 w-70" id="close-failed-message">Okay</button>\n                  </div>\n            </div>\n      `;document.getElementById("messagePortal").innerHTML+=t,lucide.createIcons(),document.getElementById("close-failed-message").addEventListener("click",()=>{document.querySelector("#failed-message").remove()})}function openUpdateAreaModal(e){const t=e.target.closest("tr").querySelectorAll("td"),a=`\n            <div id="update-area-modal" class="fixed inset-0 bg-black/30 backdrop-blur-sm flex items-center justify-center z-50">\n                  <div class="bg-card-bg dark:bg-gray-900 w-full max-w-[500px] rounded-lg shadow-2xl px-6 py-2 relative fade-in-up">\n                        <span id="close-area-update-modal" class="absolute top-3 right-4 text-gray-500 dark:text-gray-200 text-[25px] cursor-pointer">&times;</span>\n                        <h3 class="text-2xl font-bold text-gray-900 dark:text-gray-100 mb-5 text-center flex items-center justify-center gap-2 mt-4">Update Price</h3>\n                        <form id="updateAreaForm">\n                              <div class="w-full mb-6 flex flex-col gap-2">\n                                    <input type="hidden" name="area-name-update" value="${t[0].textContent.trim()}">\n                                    <input type="number" name="update-price" placeholder="Price (₱)" required class="w-full p-2 border rounded text-gray-800 dark:text-gray-100 bg-gray-50 dark:bg-gray-800" value="${parseInt(t[3].textContent.split(".")[0].replace(/[^0-9]/g,""))}">\n                                    <button type="submit" class="px-5 py-2 mt-8 bg-primary-blue dark:bg-blue-500 dark:hover:bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-700 transition"><i class="fas fa-paper-plane mr-1"></i> Update</button>\n                              </div>\n                        </form>\n                  </div>\n            </div>\n      `;document.getElementById("ratesAvailabilityPortal").innerHTML+=t[0].textContent.split("-").length>1?'\n            <div id="update-area-modal" class="fixed inset-0 bg-black/30 backdrop-blur-sm flex items-center justify-center z-50">\n                  <div class="bg-card-bg dark:bg-gray-900 w-full max-w-[500px] rounded-lg shadow-2xl px-6 py-6 relative fade-in-up">\n                        <span id="close-area-update-modal" class="absolute top-3 right-4 text-gray-500 dark:text-gray-200 text-[25px] cursor-pointer">&times;</span>\n                        <div class="flex flex-col gap-1 items-center justify-center relative mt-2">\n                              <i data-lucide="circle-x" class="w-15 h-15 text-red-500"></i>\n                              <p class="text-md font-md text-gray-900 dark:text-gray-100 mb-5 text-center flex items-center justify-center gap-2 mt-4">Cannot update. This area is currently under a promotion.</p>\n                        </div>\n                  </div>\n            </div>\n      ':a,lucide.createIcons()}async function renderTable(){let e=[];try{const t=await fetch("/availables");(await t.json()).data.forEach(t=>{e.push(t)})}catch(e){console.error("Failed to fetch data:",e)}const t=e.map(e=>{const{name:t,capacity:a}=areaTypeInfo(e.room_type);return`\n                  <tr class="fade-in-up text-gray-900 bg-gray-50 dark:bg-white/3 dark:text-gray-100 border-b border-gray-300 dark:border-gray-700 hover:bg-black/5 dark:hover:bg-white/5 transition-all">\n                        <td class="px-6 py-4 text-center font-semibold flex flex-col justify-center items-center gap-1 min-w-[450px] whitespace-nowrap">\n                              ${e.area_condition?`<span class="text-[12px] font-medium text-yellow-600 dark:text-yellow-500 bg-yellow-100 dark:bg-yellow-800 px-2 py-0.5 rounded-full">${e.promo_name}</span>`:""}\n                              ${t}\n                        </td>\n                        <td class="px-6 py-4 text-center min-w-[80px] whitespace-nowrap">${e.total_rooms}</td>\n                        <td class="px-6 py-4 text-center font-bold text-lg text-primary-blue min-w-[80px] whitespace-nowrap">${a}</td>\n                        <td class="px-6 py-4 text-center flex flex-col items-center justify-center gap-1 min-w-[250px] whitespace-nowrap">\n                              ${e.area_condition?`<div class="flex flex-col items-center gap-1">\n                                          <span class="line-through text-red-500 font-light text-sm">₱${e.orig_rate.toLocaleString("en-PH",{minimumFractionDigits:2,maximumFractionDigits:2})}</span>\n                                          <span class="text-green-600 dark:text-green-500 font-semibold text-lg">₱${e.rate.toLocaleString("en-PH",{minimumFractionDigits:2,maximumFractionDigits:2})}</span>\n                                          <span class="text-xs text-gray-500 dark:text-gray-400">Promo Applied</span>\n                                    </div>`:`<span class="text-gray-800 dark:text-gray-200">₱${e.rate.toLocaleString("en-PH",{minimumFractionDigits:2,maximumFractionDigits:2})}</span>`}\n                        </td>\n                        <td class="px-6 py-4 text-center min-w-[80px] whitespace-nowrap"><span class="font-bold text-lg text-red-500">${e.today_avail}</span></td>\n                        <td class="px-6 py-4 text-center min-w-[80px] whitespace-nowrap"><span class="font-bold text-lg text-green-500">${e.tomorrow_avail}</span></td>\n                        <td class="px-6 py-4 min-w-[100px] whitespace-nowrap">\n                              <button class="update-btn text-sm text-white bg-teal-500 py-2 px-4 rounded-sm flex gap-2 items-center justify-center hover:bg-teal-600 transition-colors" id="${e.room_type}"><i data-lucide="edit" class="text-lg"></i>Update</button>\n                        </td>\n            </tr>\n            `}).join("");document.getElementById("table2-body").innerHTML=t,lucide.createIcons()}function areaTypeInfo(e){return{name:{premium:"Premium Villa Room",standard:"Standard Villa Room",barkada:"Barkada Room",family:"Family Room",garden:"Garden View Room",cabana:"Cabana Cottage",small:"Small Cottage",big:"Big Cottage",hall:"Hall"}[e],capacity:{premium:"12",standard:"10",barkada:"8",family:"10",garden:"4",cabana:"30",small:"20",big:"50",hall:"100"}[e]}}async function updatePrice(e){e.preventDefault();const t=new FormData(e.target),a=t.get("update-price"),n=t.get("area-name-update").split(" ")[0],r=await fetch(`/update-price?price=${a}&name=${n}`,{method:"POST",headers:{"Content-Type":"application/json"}}),s=await r.json();s.success?(successMessageCard8(s.message),e.target.reset(),document.getElementById("update-area-modal").remove(),renderTable()):failedMessageCard8(s.message)}document.addEventListener("click",e=>{e.target.closest(".update-btn")&&openUpdateAreaModal(e),e.target.matches("#close-area-update-modal")&&document.getElementById("update-area-modal").remove()}),document.addEventListener("submit",e=>{e.target.matches("#updateAreaForm")&&updatePrice(e)});export function initPageRatesAndAvailability(){renderTable()}